import { useState, useEffect } from "react";
import { View, Text, FlatList, ActivityIndicator, Pressable } from "react-native";

const fakeApi = (ok) => new Promise((res, rej) => setTimeout(() => (ok ? res(["An", "Bình"]) : rej(new Error("Mất kết nối"))), 30));

export default function App() {
  const [s, setS] = useState({ status: "loading" });
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let ignore = false;
    setS({ status: "loading" });
    fakeApi(attempt > 0).then((d) => !ignore && setS({ status: "ok", data: d })).catch((e) => !ignore && setS({ status: "error", message: e.message }));
    return () => { ignore = true; };
  }, [attempt]);

  if (s.status === "loading") return <ActivityIndicator testID="spin" />;
  if (s.status === "error") return <View><Text testID="err">{s.message}</Text><Pressable testID="retry" onPress={() => setAttempt(attempt + 1)}><Text>Thử lại</Text></Pressable></View>;
  if (s.data.length === 0) return <Text testID="empty">Chưa có dữ liệu</Text>;
  return <FlatList data={s.data} keyExtractor={(x) => x} renderItem={({ item }) => <Text testID="row">{item}</Text>} />;
}

