import { useState, useEffect } from "react";
import { View, Text, Pressable } from "react-native";

const api = (attempt) => new Promise((res, rej) => setTimeout(() => (attempt === 0 ? rej(new Error("Offline")) : res("ok")), 30));

export default function App() {
  const [attempt, setAttempt] = useState(0);
  const [s, setS] = useState({ status: "loading" });
  useEffect(() => {
    let ignore = false;
    setS({ status: "loading" });
    api(attempt).then(() => !ignore && setS({ status: "ok" })).catch((e) => !ignore && setS({ status: "error", message: e.message }));
    return () => { ignore = true; };
  }, [attempt]);
  return (
    <View>
      {s.status === "error" && <Text testID="err">{s.message}</Text>}
      {s.status === "ok" && <Text testID="ok">Done</Text>}
      <Pressable testID="retry" onPress={() => setAttempt(attempt + 1)}><Text>Thử lại</Text></Pressable>
    </View>
  );
}
